import { describe, it, expect } from "vitest";
import { runScenario } from "./claim-office.js";

describe("MHPCO Claim Office", () => {
  describe("quote — base premiums", () => {
    it("empty item list → premium 5 G (only the processing fee)", () => {
      const result = runScenario({
        customer: { yearsWithMHPCO: 0 },
        steps: [{ op: "quote", items: [] }],
      });

      expect(result).toEqual({ results: [{ premium: 5 }] });
    });
    it("a sword → base premium 100 G, +10 G first insurance, +5 G fee → premium 115 G", () => {
      const result = runScenario({
        customer: { yearsWithMHPCO: 0 },
        steps: [{ op: "quote", items: [{ type: "sword" }] }],
      });

      expect(result).toEqual({ results: [{ premium: 115 }] });
    });
    it("an amulet → base premium 60 G, +6 G first insurance, +5 G fee → premium 71 G", () => {
      const result = runScenario({
        customer: { yearsWithMHPCO: 0 },
        steps: [{ op: "quote", items: [{ type: "amulet" }] }],
      });

      expect(result).toEqual({ results: [{ premium: 71 }] });
    });
    it("a staff → base premium 80 G, +8 G first insurance, +5 G fee → premium 93 G", () => {
      const result = runScenario({
        customer: { yearsWithMHPCO: 0 },
        steps: [{ op: "quote", items: [{ type: "staff" }] }],
      });

      expect(result).toEqual({ results: [{ premium: 93 }] });
    });
    it("a potion → base premium 40 G, +4 G first insurance, +5 G fee → premium 49 G", () => {
      const result = runScenario({
        customer: { yearsWithMHPCO: 0 },
        steps: [{ op: "quote", items: [{ type: "potion" }] }],
      });

      expect(result).toEqual({ results: [{ premium: 49 }] });
    });
    it("a single rune → base premium 25 G, +2.5 G first insurance, +5 G fee → premium 33 G", () => {
      const result = runScenario({
        customer: { yearsWithMHPCO: 0 },
        steps: [{ op: "quote", items: [{ type: "rune" }] }],
      });

      expect(result).toEqual({ results: [{ premium: 33 }] });
    });
    it.todo("a single moonstone → base premium 25 G, premium 30 G with fee");
  });

  describe("quote — building block of 3 alike components", () => {
    it.todo("2 runes → 50 G base premium");
    it.todo("3 runes → 60 G base premium (block applies)");
    it.todo("4 runes → 100 G base premium (no block — block requires exactly 3)");
    it.todo("7 runes → 175 G base premium");
    it.todo("2 runes + 1 moonstone → 75 G base premium (no block: different types)");
    it.todo("3 runes + 3 moonstones → 120 G base premium (two separate blocks)");
  });

  describe("quote — item-specific modifiers", () => {
    it.todo("cursed sword adds 50 % of its base premium → 150 G base + modifiers");
    it.todo("sword with exactly enchantment 5 → 30 % high-enchantment surcharge applies");
    it.todo("sword with enchantment 4 → no high-enchantment surcharge");
    it.todo("cursed sword with enchantment 5 → both surcharges apply");
  });

  describe("quote — policy-wide modifiers", () => {
    it.todo("customer with exactly 2 years with MHPCO → 20 % loyalty discount applies");
    it.todo("customer with 1 year → no loyalty discount");
    it.todo("first quote in a scenario carries the 10 % initial assessment surcharge");
    it.todo("the second quote in a scenario receives the 15 % follow-up contract discount");
  });

  describe("quote — modifier scope on multi-item policies", () => {
    it.todo(
      "cursed sword (100 G) + plain amulet (60 G) → 160 G policy base, curse adds 50 G → 210 G before further modifiers and fee",
    );
    it.todo("policy-wide modifiers apply to the sum of all item base premiums");
  });

  describe("quote — rounding in the MHPCO's favor", () => {
    it.todo("a premium calculation that yields 197.5 G → final premium 198 G (rounded up)");
    it.todo("intermediate amounts are kept as fractions; only the final premium is rounded");
  });

  describe("quote — integration examples", () => {
    it.todo("newcomer (0 years) with a cursed sword (steel, enchantment 3) → premium 165 G");
    it.todo(
      "long-standing customer (3 years), second quote, cursed sword enchantment 7 → premium 160 G",
    );
  });

  describe("claim — standard reimbursement", () => {
    it.todo("regular sword (steel, enchantment 3), damage 500 G → payout 400 G");
    it.todo("damage to a rune (value 250 G), damage 200 G → payout 100 G");
  });

  describe("claim — special clauses", () => {
    it.todo("dragon-material sword, enchantment 5, damage 800 G → payout 700 G");
    it.todo("steel sword, enchantment 9, damage 1000 G → payout 400 G (50 % then deductible)");
    it.todo("dragon-material sword, enchantment 9, damage 1000 G → payout 400 G (50 % rule wins)");
    it.todo(
      "dragon-material sword with exactly enchantment 8, damage 1000 G → payout 400 G (threshold)",
    );
  });

  describe("claim — deductible per damage event", () => {
    it.todo("dragon attack damages sword (500 G) and amulet (300 G) → payout 600 G");
  });

  describe("claim — cap", () => {
    it.todo("a policy covering a sword and an amulet → insurance sum 1600 G, cap 3200 G");
    it.todo("a cursed sword → cap 2000 G (premium modifiers do not raise the cap)");
    it.todo("a policy covering a sword and 3 runes → insurance sum 1750 G (block affects premium only)");
    it.todo("sword policy (cap 2000 G), first claim of 1500 G → payout 1400 G, remainingCap 600 G");
    it.todo("second claim of 1500 G → payout 600 G, remainingCap 0 G (reduced to remaining cap)");
  });

  describe("claim — rounding in the MHPCO's favor", () => {
    it.todo("a payout calculation that yields 350.5 G → final payout 350 G (rounded down)");
  });

  describe("multiple items of the same type", () => {
    it.todo("a policy covering two swords → insurance sum 2000 G, cap 4000 G");
    it.todo("two sword damage entries → each treated as a separate damage with its own deductible");
    it.todo("more damage entries of a type than insured (2 sword damages, 1 sword) → error");
  });

  describe("CLI", () => {
    it.todo("reads a scenario from stdin and writes results in step order to stdout");
    it.todo("quote with an unknown item type (broomstick) → non-zero exit, error on stderr, no stdout results");
    it.todo("claim referencing an item not part of the policy → non-zero exit and error on stderr");
    it.todo("claim with a damage amount of -200 → non-zero exit and error on stderr");
  });
});

