export interface Customer {
  yearsWithMHPCO: number;
}

export interface Item {
  type: string;
  material?: string;
  enchantment?: number;
  cursed?: boolean;
}

export interface QuoteStep {
  op: "quote";
  items: Item[];
}

export interface Damage {
  itemType: string;
  amount: number;
}

export interface ClaimStep {
  op: "claim";
  policy: number;
  incident: { cause: string; damages: Damage[] };
}

export type Step = QuoteStep | ClaimStep;

export interface Scenario {
  customer: Customer;
  steps: Step[];
}

export type StepResult = { premium: number } | { payout: number; remainingCap: number };

export interface ScenarioResult {
  results: StepResult[];
}

const PROCESSING_FEE = 5;
const INITIAL_ASSESSMENT_SURCHARGE = 0.1;

const BASE_PREMIUMS: Record<string, number> = {
  sword: 100,
  amulet: 60,
  staff: 80,
  potion: 40,
  rune: 25,
  moonstone: 25,
};

/** Premiums round up: fractions of a Gold piece go to the MHPCO, never the customer. */
const roundPremiumInMHPCOFavour = (amount: number): number => Math.ceil(amount);

const COMPONENT_BLOCK_SIZE = 3;
const COMPONENT_BLOCK_PREMIUM = 60;

const countsByType = (items: Item[]): Map<string, number> =>
  items.reduce(
    (counts, item) => counts.set(item.type, (counts.get(item.type) ?? 0) + 1),
    new Map<string, number>(),
  );

/** A group of exactly three alike items is a building block, priced at a flat rate. */
const basePremiumForGroup = (type: string, count: number): number =>
  count === COMPONENT_BLOCK_SIZE
    ? COMPONENT_BLOCK_PREMIUM
    : count * BASE_PREMIUMS[type];

const policyBasePremiumOf = (items: Item[]): number =>
  [...countsByType(items)].reduce(
    (total, [type, count]) => total + basePremiumForGroup(type, count),
    0,
  );

const quote = (step: QuoteStep): StepResult => {
  const policyBasePremium = policyBasePremiumOf(step.items);
  return {
    premium: roundPremiumInMHPCOFavour(
      policyBasePremium +
        policyBasePremium * INITIAL_ASSESSMENT_SURCHARGE +
        PROCESSING_FEE,
    ),
  };
};

const runStep = (step: Step): StepResult => {
  if (step.op === "quote") return quote(step);
  throw new Error(`Unsupported step: ${step.op}`);
};

export const runScenario = (scenario: Scenario): ScenarioResult => ({
  results: scenario.steps.map(runStep),
});

