  if ((item.enchantment ?? 0) >= SEVERE_ENCHANTMENT_LEVEL) {
    return SEVERE_ENCHANTMENT_REIMBURSEMENT;
  }
  if (item.material === DRAGON_MATERIAL) return FULL_REIMBURSEMENT;
  return FULL_REIMBURSEMENT;
};

/** A damage entry names its item by type; the policy says which item that is. */
const insuredItemFor = (damage: Damage, items: Item[]): Item => {
  const item = items.find((candidate) => candidate.type === damage.itemType);
  if (!item) throw new Error(`Policy does not cover a ${damage.itemType}`);
  return item;
};

/** A policy issued by a quote step, tracking how much of its cap remains. */
interface Policy {
  items: Item[];
  remainingCap: number;
}

const insuranceSum = (items: Item[]): number =>
  items.reduce((sum, item) => sum + INSURANCE_VALUES[item.type], 0);

const openPolicy = (items: Item[]): Policy => ({
  items,
  remainingCap: CAP_MULTIPLIER * insuranceSum(items),
});

